from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')
s = re.sub(r'\n<style id="v94-evolution-scores">.*?</style>\s*<script id="v94-evolution-scores">.*?</script>\s*', '\n', s, flags=re.S)

patch = r'''
<style id="v94-evolution-scores">
.v94-evolution-intro{background:linear-gradient(135deg,#fffdf8,#f3f0e9);border:1px solid #ddd8cf}.v94-kicker{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#777;font-weight:700}.v94-evolution-intro h2{margin:4px 0 6px;font-family:Georgia,serif;font-size:29px}.v94-evolution-intro p{margin:0;color:#666}.v94-score-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.v94-score-card{border:1px solid #ddd8cf;border-radius:14px;background:#fff;padding:14px}.v94-score-card .label{font-size:13px;font-weight:700;line-height:1.25}.v94-score-card .value{font-size:25px;font-weight:800;margin-top:5px}.v94-score-card .delta{font-size:12px;color:#26733d;margin-top:3px;font-weight:700}.v94-average{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:14px;padding:14px 16px;border-radius:13px;background:#f7f5f1;border:1px solid #ddd8cf}.v94-average strong{font-size:24px}.v94-average span{color:#666;font-size:13px}.v94-head{margin:0 0 10px;font-size:20px}.v94-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.v94-analysis{padding:18px;border-radius:14px;border:1px solid #ddd8cf;background:#fff}.v94-analysis h3{margin:0 0 7px;font-size:17px}.v94-analysis p{margin:0;color:#555;line-height:1.55}.v94-positive{background:#f5faf6;border-color:#d7e8db}.v94-focus{background:#faf8f2;border-color:#e6deca}.v94-bars{display:grid;gap:11px}.v94-bar{display:grid;grid-template-columns:minmax(145px,1fr) 42px;gap:8px;align-items:center}.v94-bar-track{height:10px;background:#e8e5df;border-radius:999px;overflow:hidden;margin-top:5px}.v94-bar-fill{height:100%;background:#555;border-radius:999px}.v94-bar-label{font-size:13px;font-weight:700}.v94-periods{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.v94-period{padding:13px;border:1px solid #ddd8cf;border-radius:12px;background:#faf9f6;text-align:center}.v94-period strong{display:block;font-size:20px}.v94-period span{font-size:12px;color:#777}.v94-records{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.v94-record{padding:14px;border:1px solid #ddd8cf;border-radius:12px;background:#fff}.v94-record strong{display:block;font-size:18px;margin-top:3px}.v94-record span{font-size:12px;color:#777}.v94-balance{margin-top:12px;padding:13px 15px;border-radius:12px;background:#f7f5f1;color:#555;line-height:1.5}.v94-reflection{background:linear-gradient(135deg,#fffdf8,#f5f2eb);border:1px solid #ddd8cf}.v94-reflection h2{font-family:Georgia,serif;margin-top:0}.v94-reflection p{font-size:16px;line-height:1.65;color:#4e4a43}.v94-question{margin-top:15px;padding:14px;border-left:4px solid #777;background:#fff;font-style:italic;color:#555;border-radius:0 10px 10px 0}.v94-muted{color:#777;font-size:13px}@media(max-width:800px){.v94-score-cards{grid-template-columns:1fr 1fr}.v94-grid{grid-template-columns:1fr}.v94-periods{grid-template-columns:1fr 1fr}.v94-records{grid-template-columns:1fr}}@media(max-width:520px){.v94-score-cards{grid-template-columns:1fr}.v94-average{align-items:flex-start;flex-direction:column}.v94-bar{grid-template-columns:minmax(120px,1fr) 38px}}
</style>
<script id="v94-evolution-scores">
(function(){
  const D=[['presence','🧘 Pleine conscience'],['impulse_control','🔥 Maîtrise des impulsions'],['values_coherence','🧭 Cohérence avec mes valeurs'],['self_relation','❤️ Relation à moi-même']];
  const n=v=>{const x=Number(v);return Number.isFinite(x)?x:null};
  const avg=(rows,k)=>{const a=rows.map(r=>n(r[k])).filter(x=>x!==null);return a.length?a.reduce((x,y)=>x+y,0)/a.length:null};
  const rowAvg=r=>{const a=D.map(d=>n(r[d[0]])).filter(x=>x!==null);return a.length?a.reduce((x,y)=>x+y,0)/a.length:null};
  const sg=x=>x===null?'—':(x>0?'+':'')+x.toFixed(1);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function prepare(){const s=document.getElementById('evolutionSection');if(!s||s.dataset.v94)return;s.dataset.v94='1';s.innerHTML=`
    <div class="card v94-evolution-intro"><div class="v94-kicker">Observer · comprendre · avancer</div><h2>📈 Évolution de mes scores</h2><p>Mes scores sont des repères pour observer mon chemin, pas des notes pour me juger.</p><div id="v94Cards" class="v94-score-cards"></div><div id="v94Average" class="v94-average"></div></div>
    <div class="card score-chart-card"><h2 class="v94-head">📊 Voir mon évolution</h2><p class="v94-muted">Les courbes montrent les variations jour après jour. Une variation fait partie du chemin : l’important est la tendance dans le temps.</p><div class="score-chart-toolbar"><button id="chart7Button" class="secondary" onclick="setChartRange(7)">7 jours</button><button id="chart15Button" class="secondary" onclick="setChartRange(15)">15 jours</button><button id="chart30Button" class="secondary" onclick="setChartRange(30)">30 jours</button><button id="chart45Button" class="secondary" onclick="setChartRange(45)">45 jours</button><button id="chart60Button" class="secondary" onclick="setChartRange(60)">60 jours</button><button id="chart75Button" class="secondary" onclick="setChartRange(75)">75 jours</button><button id="chart90Button" class="secondary active" onclick="setChartRange(90)">90 jours</button></div><div class="score-chart-wrap"><div id="scoreEvolutionChartContainer" aria-label="Graphique d’évolution des scores"></div></div><div id="chartStatus" class="empty hidden"></div></div>
    <div class="card"><h2 class="v94-head">🧠 Ce que mes scores racontent</h2><div id="v94Analysis" class="v94-grid"></div></div>
    <div class="card"><h2 class="v94-head">⚖️ Mon équilibre actuel</h2><div id="v94Bars" class="v94-bars"></div><div id="v94Balance" class="v94-balance"></div></div>
    <div class="card"><h2 class="v94-head">🌱 Mes tendances récentes</h2><div id="v94Periods" class="v94-periods"></div></div>
    <div class="card"><h2 class="v94-head">🏆 Mes repères</h2><div id="v94Records" class="v94-records"></div></div>
    <div class="card v94-reflection"><h2>🪞 Mon bilan</h2><div id="v94Reflection"></div></div>`;}
  function render(){prepare();const rows=(typeof dailyScoreHistory!=='undefined'?dailyScoreHistory:[]).filter(r=>Number.isFinite(Number(r.day_number))).sort((a,b)=>Number(a.day_number)-Number(b.day_number));if(!document.getElementById('v94Cards'))return;if(!rows.length){document.getElementById('v94Cards').innerHTML='<div class="v94-muted" style="grid-column:1/-1">Tes premiers scores apparaîtront ici au fil des journées.</div>';document.getElementById('v94Average').innerHTML='<strong>—</strong><span>Commence à renseigner tes scores : ton évolution se construira progressivement.</span>';return}const first=rows[0],recent=rows.slice(-7),last=rows[rows.length-1],firstA=rowAvg(first),lastA=rowAvg(last);document.getElementById('v94Cards').innerHTML=D.map(d=>{const v=avg(recent,d[0])??avg(rows,d[0]),b=n(first[d[0]]),delta=v!==null&&b!==null?v-b:null;return `<div class="v94-score-card"><div class="label">${d[1]}</div><div class="value">${v===null?'—':v.toFixed(1)} <small>/10</small></div><div class="delta">${delta===null?'En construction':(delta>0?'↑ ':'')+sg(delta)+' depuis le début'}</div></div>`}).join('');document.getElementById('v94Average').innerHTML=`<div><span>Moyenne des 7 dernières journées</span><br><strong>${lastA===null?'—':lastA.toFixed(1)+' / 10'}</strong></div><span>${firstA!==null&&lastA!==null?'Évolution depuis J'+first.day_number+' : <strong>'+sg(lastA-firstA)+'</strong>':'Continue à avancer à ton rythme.'}</span>`;
    const prev=rows.slice(-14,-7),tr=D.map(d=>({d,cur:avg(recent,d[0]),prev:avg(prev,d[0])})).filter(x=>x.cur!==null),best=[...tr].sort((a,b)=>(b.cur-(b.prev??b.cur))-(a.cur-(a.prev??a.cur)))[0],low=[...tr].sort((a,b)=>a.cur-b.cur)[0],strongest=D.map(d=>({d,delta:(avg(recent,d[0])??0)-(n(first[d[0]])??avg(recent,d[0])??0)})).sort((a,b)=>b.delta-a.delta)[0];
    document.getElementById('v94Analysis').innerHTML=`<div class="v94-analysis v94-positive"><h3>💪 Ce qui évolue le plus</h3><p>${strongest?`<strong>${esc(strongest.d[1])}</strong> montre actuellement la progression la plus marquée depuis le début (${sg(strongest.delta)}). C’est un beau repère de ce que tu es en train de construire.`:'Tes premières données se constituent. Chaque journée enrichira cette lecture.'}</p></div><div class="v94-analysis v94-focus"><h3>🌱 Une dimension à explorer</h3><p>${low?`<strong>${esc(low.d[1])}</strong> évolue à son propre rythme (${low.cur.toFixed(1)}/10 sur les 7 dernières journées). C’est simplement une piste intéressante pour observer ce qui t’aide à progresser.`:'Tes données sont encore trop récentes pour dégager une tendance.'}</p></div><div class="v94-analysis"><h3>🌊 Ma dynamique récente</h3><p>${best&&best.prev!==null&&best.cur-best.prev>0.2?`Les derniers jours montrent une évolution encourageante, notamment sur <strong>${esc(best.d[1])}</strong> (${sg(best.cur-best.prev)} par rapport aux 7 jours précédents). Continue à observer ce qui fonctionne pour toi.`:best&&best.prev!==null&&best.cur-best.prev<-0.2?`Les derniers jours apportent de nouvelles informations sur ton parcours. <strong>${esc(best.d[1])}</strong> varie en ce moment : prends cette évolution comme une occasion d’observer ce qui t’aide, sans te juger.`:'Tes scores récents sont globalement stables. C’est un bon moment pour consolider ce que tu as déjà construit.'}</p></div><div class="v94-analysis"><h3>🧭 Ma direction</h3><p>${lastA!==null&&firstA!==null&&lastA>firstA?`Ta moyenne actuelle est supérieure à celle de ton premier jour. <strong>Tu avances.</strong> Le parcours se construit dans la répétition des petits pas, pas dans la recherche de la perfection.`:'Ton parcours se dessine progressivement. Laisse les données s’accumuler et observe simplement ce qu’elles viennent t’apprendre.'}</p></div>`;
    const vals=D.map(d=>({d,v:avg(recent,d[0])})).filter(x=>x.v!==null),min=Math.min(...vals.map(x=>x.v)),max=Math.max(...vals.map(x=>x.v));document.getElementById('v94Bars').innerHTML=vals.map(x=>`<div class="v94-bar"><div><div class="v94-bar-label">${esc(x.d[1])}</div><div class="v94-bar-track"><div class="v94-bar-fill" style="width:${x.v*10}%"></div></div></div><strong>${x.v.toFixed(1)}</strong></div>`).join('');document.getElementById('v94Balance').innerHTML=vals.length===4?`Tes quatre dimensions se situent actuellement entre <strong>${min.toFixed(1)}</strong> et <strong>${max.toFixed(1)}</strong>. ${max-min<2?'Ton équilibre est relativement harmonieux.':'Ces nuances donnent des indications intéressantes sur ton chemin : observe-les avec curiosité.'}`:'Les dimensions se rempliront progressivement.';
    const chunks=[rows.slice(0,Math.min(7,rows.length)),rows.slice(0,Math.min(14,rows.length)),recent,rows],names=['Début du parcours','Premiers repères','7 derniers jours','Ensemble des journées'];document.getElementById('v94Periods').innerHTML=chunks.map((r,i)=>{const a=r.map(rowAvg).filter(x=>x!==null),v=a.length?a.reduce((x,y)=>x+y,0)/a.length:null;return `<div class="v94-period"><strong>${v===null?'—':v.toFixed(1)+'/10'}</strong><span>${names[i]}</span></div>`}).join('');const bestDay=rows.map(r=>({r,v:rowAvg(r)})).filter(x=>x.v!==null).sort((a,b)=>b.v-a.v)[0];document.getElementById('v94Records').innerHTML=`<div class="v94-record">🏆 Meilleur score global<strong>${bestDay?bestDay.v.toFixed(1)+'/10':'—'}</strong><span>${bestDay?'Jour '+bestDay.r.day_number:'À venir'}</span></div><div class="v94-record">📈 Évolution globale<strong>${firstA!==null&&lastA!==null?sg(lastA-firstA):'—'}</strong><span>entre le début et maintenant</span></div><div class="v94-record">🌱 Journées renseignées<strong>${rows.length}</strong><span>sur 91</span></div>`;const dir=firstA!==null&&lastA!==null?lastA-firstA:0;document.getElementById('v94Reflection').innerHTML=`<p><strong>${dir>0.3?'Tu avances, et tes données commencent à raconter une vraie évolution.':dir<-0.3?'Ton parcours continue de se construire. Les variations actuelles sont simplement de nouvelles informations à observer.':'Ton parcours se construit progressivement. Chaque journée apporte un repère supplémentaire.'}</strong></p><p>${overallText(rows)}</p><div class="v94-question">🌿 Si je poursuis dans cet esprit pendant les prochaines semaines, qu’est-ce que j’aimerais voir évoluer concrètement dans ma vie ?</div>`;if(typeof renderScoreEvolutionChart==='function')renderScoreEvolutionChart();}
  function overallText(rows){const a=rows.map(rowAvg).filter(x=>x!==null);if(!a.length)return'Chaque nouvelle journée permettra de rendre cette lecture plus précise.';return`Sur l’ensemble des journées renseignées, ma moyenne est de <strong>${(a.reduce((x,y)=>x+y,0)/a.length).toFixed(1)}/10</strong>. Ce chiffre n’est pas une note : c’est une photographie de mon chemin à cet instant.`}
  function hook(){render()}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(hook,100));else setTimeout(hook,100);window.addEventListener('load',()=>setTimeout(hook,900));
  const oldShow=window.showSection;if(typeof oldShow==='function')window.showSection=function(section){const r=oldShow.apply(this,arguments);if(section==='evolution')setTimeout(render,100);return r};
})();
</script>
'''
s = s.replace('</body>', patch + '\n</body>', 1)
p.write_text(s, encoding='utf-8')
print('V94 evolution scores applied')
